create or replace function public.admin_website_page( p_search text default null, p_status text default null, p_limit integer default 50, p_offset integer default 0 ) returns table (id uuid, total bigint) language sql stable security definer set search_path = public as $$ with matched as ( select w.id, w.updated_at from public.websites w left join public.categories c on c.id = w.primary_category_id where (p_status is null or p_status = 'all' or w.status::text = p_status) and ( coalesce(btrim(p_search), '') = '' or position( lower(btrim(p_search)) in lower(w.domain || ' ' || coalesce(w.title, '') || ' ' || coalesce(c.slug, '')) ) > 0 ) ) select matched.id, count(*) over () as total from matched order by matched.updated_at desc, matched.id asc limit greatest(1, least(coalesce(p_limit, 50), 250)) offset greatest(0, coalesce(p_offset, 0)); $$;
comment on function public.admin_website_page(text, text, integer, integer) is 'One page of the admin website table. Returns ids and the total; the caller maps the rows with the admin select it already has.';
create or replace function public.admin_website_ids( p_search text default null, p_status text default null ) returns table (id uuid) language sql stable security definer set search_path = public as $$ select w.id from public.websites w left join public.categories c on c.id = w.primary_category_id where (p_status is null or p_status = 'all' or w.status::text = p_status) and ( coalesce(btrim(p_search), '') = '' or position( lower(btrim(p_search)) in lower(w.domain || ' ' || coalesce(w.title, '') || ' ' || coalesce(c.slug, '')) ) > 0 ) order by w.updated_at desc, w.id asc; $$;
comment on function public.admin_website_ids(text, text) is 'Every listing id the admin filter matches, for the header checkbox that selects a whole filter rather than a page. Ids only - no domains, no metrics, nothing a page would render.';
